LISTING 10.2 GoalScript.cs
using UnityEngine;
public class GoalScript : MonoBehaviour
{
public bool isSolved = false;
void OnTriggerEnter (Collider collider)
{
GameObject collidedWith = collider.gameObject;
if (collidedWith.tag == gameObject.tag)
{
isSolved = true;
GetComponent<Light>().enabled = false;
Destroy (collidedWith);
}
}
}
As you can see in the script, the OnTriggerEnter() method checks the tag of each object
that contacts it against its own tag. If they match, the object is destroyed, the goal is flagged as
solved, and that goal’s light is disabled.
